using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.AshMorel;

/// <summary>
/// Ash morels, honeycomb-capped mushrooms that spring up in the ash after a fire, in the Ashlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py. Smoke Puffs picked in the Ashlands can also give them.
/// </summary>
public class AshMorel : ForageableBase
{
    /// <summary>
    /// Prefab name of the ash morel item.
    /// </summary>
    public const string PrefabName = "WhiteHiltAshMorel";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Ash Morel";

    /// <inheritdoc/>
    protected override string Description => "A mushroom with a cap like a honeycomb that springs up in the ash after a fire. Cooks prize it for its deep, smoky taste.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Mushroom";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_SmokePuff";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.25f;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "ashmorel", 0.14f);
    }
}
